"""Text reports."""


def format_row(name, value):
    """One report line."""
    return "%-20s%10.2f" % (name, value)


def report(rows, totals=False):
    """Render rows, with a totals line if asked."""
    lines = [format_row(n, v) for n, v in rows]
    if totals:
        lines.append(format_row("TOTAL", sum(v for _, v in rows)))
    return "\n".join(lines)


def report_csv(rows):
    """Render rows as CSV."""
    return "\n".join("%s,%.2f" % (n, v) for n, v in rows)


def header(title):
    """A title line as wide as a report line."""
    return format_row(title.upper(), 0)[:20].rstrip()
===== tests/test_report.py
import unittest

from src.report import format_row, report, report_csv, header


class TestReport(unittest.TestCase):
    def test_format_row(self):
        self.assertEqual(format_row("rent", 12.5), "%-20s%10.2f" % ("rent", 12.5))

    def test_report(self):
        self.assertEqual(report([("a", 1)]), "%-20s%10.2f" % ("a", 1))

    def test_totals(self):
        self.assertTrue(report([("a", 1), ("b", 2)], totals=True).endswith("3.00"))

    def test_csv(self):
        self.assertEqual(report_csv([("a", 1)]), "a,1.00")

    def test_header(self):
        self.assertEqual(header("q3 costs"), "Q3 COSTS")
